async collectSkillObservations(taskId, runId) {
    const hint = this.store.sqlite.prepare("SELECT r.snapshot_hash AS snapshotHash,i.session_id AS sessionId FROM capability_runs r JOIN capability_session_identities i ON i.task_id=r.task_id WHERE r.run_id=? AND r.task_id=? AND r.state='active' AND r.revocation_state='open'").get(runId, taskId);
    if (!hint?.sessionId) {
      this.forgetSkillObservations(runId);
      return;
    }
    let state2 = this.observationPolls.get(runId);
    if (!state2 || state2.taskId !== taskId || state2.snapshotHash !== hint.snapshotHash) {
      if (this.observationPolls.size >= 128) this.observationPolls.delete(this.observationPolls.keys().next().value);
      state2 = { taskId, snapshotHash: hint.snapshotHash, revision: null };
      this.observationPolls.set(runId, state2);
    }
    const revision2 = this.deps.skillObservationRevision ? await this.deps.skillObservationRevision(runId, hint.snapshotHash) : null;
    if (this.deps.skillObservationRevision && (!revision2 || revision2 === state2.revision)) return;
    const value = await this.inspect(taskId, runId);
    if (this.observationPolls.get(runId) === state2 && value.snapshotHash === hint.snapshotHash && value.currentRun?.id === runId && value.currentRun.preparation?.state === "prepared" && !value.currentRun.preparationIssue && !value.currentRun.skillObservationIssue && value.applications.every((app) => !app.packageHash || app.resourceState === "verified")) state2.revision = revision2;
  }
  forgetSkillObservations(runId) {
    this.observationPolls.delete(runId);
  }
